#!/usr/bin/env python3
"""Generate src/lib/stations/assets.generated.ts from docs/baseline/assets-baseline.json (original app's synthetic asset counts)."""
import json
d = json.load(open("docs/baseline/assets-baseline.json"))["byRecordId"]
open("src/lib/stations/assets.generated.ts", "w").write(
"// GENERATED by scripts/gen-assets.py from docs/baseline/assets-baseline.json — do not edit by hand.\n"
"// SYNTHETIC DEMO asset counts carried over from the original app. NOT a verified inventory and NOT DART data.\n"
"export type AssetKey = \"elevators\" | \"cameras\" | \"stairwells\" | \"trash_cans\" | \"bus_covers\";\n"
"export type AssetCounts = Record<AssetKey | `${AssetKey}_ok`, number>;\n"
"export const ASSET_COUNTS: Record<string, AssetCounts> = " + json.dumps(d, separators=(",", ":")) + ";\n")
print(len(d))
